/**
 * Playwright stealth script for VK Video Downloader
 * Bypasses anti-scraping protections by masking automation fingerprints
 */

// Mask webdriver property
Object.defineProperty(navigator, 'webdriver', {
    get: () => undefined
});

// Mask plugins property
Object.defineProperty(navigator, 'plugins', {
    get: () => [1, 2, 3, 4, 5]
});

// Mask languages property
Object.defineProperty(navigator, 'languages', {
    get: () => ['ru-RU', 'ru', 'en-US', 'en']
});

// Mask Chrome property
Object.defineProperty(navigator, 'chrome', {
    get: () => ({
        app: { isInstalled: false, installed: false },
        webstore: { onInstallStageChanged: {} },
        runtime: {}
    })
});

// Mask permissions
const originalQuery = window.navigator.permissions && window.navigator.permissions.query;
window.navigator.permissions && (window.navigator.permissions.query = parameters => (
    parameters.name === 'notifications' ?
        Promise.resolve({ state: Notification.permission }) :
        originalQuery(parameters)
));

// Mask Chrome object in window
window.chrome = {
    runtime: {},
    loadTimes: () => undefined,
    csi: () => undefined
};

// Remove puppeteer-specific properties
delete window.__gCrWeb;
delete window.__webdriverScriptFn;
delete window.__webdriverScript;
delete window.cron;
delete window.cronData;

// Mask automation-controlled features
const newProto = navigator.__proto__;
delete newProto.webdriver;

// Mask automation browser properties
Object.defineProperty(navigator, 'automation', {
    get: () => undefined
});

// Add realistic screen properties
Object.defineProperty(screen, 'availWidth', { get: () => 1920 });
Object.defineProperty(screen, 'availHeight', { get: () => 1040 });